-- TRANSITIQ admin write policy optimization; applied to hosted project.
drop policy if exists "admins manage stops" on public.stops;
create policy "admins insert stops" on public.stops for insert to authenticated with check(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid())));
create policy "admins update stops" on public.stops for update to authenticated using(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid()))) with check(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid())));
create policy "admins delete stops" on public.stops for delete to authenticated using(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid())));
